// Decodifica el JWT del header Authorization para obtener el clinic_id
const headers = $input.first().json.headers || {};
const authHeader = (headers.authorization || headers.Authorization || '').toString();
const token = authHeader.replace(/^Bearer\s+/i, '').trim();

if (!token) {
  throw new Error('Authorization token requerido');
}

const parts = token.split('.');
if (parts.length !== 3) {
  throw new Error('Formato de token inválido');
}

try {
  const base64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
  const padding = '='.repeat((4 - base64.length % 4) % 4);
  const payload = JSON.parse(Buffer.from(base64 + padding, 'base64').toString('utf8'));
  const clinicId = payload.clinic_id || payload.clinicId || payload.clinic;
  if (!clinicId) throw new Error('clinic_id no encontrado en el token');
  return [{ json: { clinic_id: String(clinicId) } }];
} catch (e) {
  throw new Error('Error al decodificar token: ' + e.message);
}

const items = $input.all();

if (items.length === 1 && items[0].json.error) {
  throw new Error('Error en base de datos: ' + (items[0].json.error?.message || String(items[0].json.error)));
}

const rows = items.map(i => i.json);
const counts = { receptionist: { total: 0 }, admin: { total: 0 }, super_admin: { total: 0 } };
const users = [];
for (const row of rows) {
  const key = row.role_key;
  if (key && key !== 'other') {
    counts[key] = counts[key] || { total: 0 };
    counts[key].total++;
    users.push(row);
  }
}
return [{ json: { counts, users } }];
